/**
 * CutsceneImages.js
 * 
 * Diccionario centralizado y Asset Pipeline para cinemáticas estilo Anime Retro / PC-98.
 * Provee la estructura definitiva de imágenes WebP en Base64/Data-URI y placeholders
 * nítidos de alta definición para las 4 escenas maestras del juego:
 * 
 * 1. SCENE_AI_ALEX_WARNING (Encuentro con Mister AI Alex y el Microondas Cuántico)
 * 2. SCENE_JAIL_ARREST (Sentencia y porrazo eléctrico del Carcelero Real)
 * 3. SCENE_DEUS_PURIFICATION (Redención sagrada y purificación en Reinos Condenados)
 * 4. SCENE_ENDING_VICTORY (Clausura, reseteo del universo y El Ojete Dorado)
 */

/**
 * Renderiza proceduralmente un fondo cibernético retro de 320x180 px
 * con gradiente abisal, rejilla de perspectiva 3D, scanlines y tipografía retro.
 */
export function renderFallbackToContext(ctx, width = 320, height = 180, title = 'SYSTEM ARCHIVE', subtitle = 'BUFFERING SCENE...', theme = 'cyber') {
  ctx.save();
  ctx.imageSmoothingEnabled = false;

  // 1. Fondo degradado abisal
  const bgGrad = ctx.createLinearGradient(0, 0, 0, height);
  if (theme === 'jail') {
    bgGrad.addColorStop(0, '#090508');
    bgGrad.addColorStop(0.5, '#190a10');
    bgGrad.addColorStop(1, '#050204');
  } else if (theme === 'divine') {
    bgGrad.addColorStop(0, '#06030c');
    bgGrad.addColorStop(0.5, '#170829');
    bgGrad.addColorStop(1, '#04020a');
  } else if (theme === 'danger') {
    bgGrad.addColorStop(0, '#0d0408');
    bgGrad.addColorStop(0.5, '#220813');
    bgGrad.addColorStop(1, '#080205');
  } else if (theme === 'toxic' || theme === 'garbage_collector') {
    bgGrad.addColorStop(0, '#020f07');
    bgGrad.addColorStop(0.5, '#062612');
    bgGrad.addColorStop(1, '#010804');
  } else if (theme === 'recursive' || theme === 'stack_overflow') {
    bgGrad.addColorStop(0, '#0c0414');
    bgGrad.addColorStop(0.5, '#230b3b');
    bgGrad.addColorStop(1, '#07020d');
  } else if (theme === 'microwave' || theme === 'prototype_microwave') {
    bgGrad.addColorStop(0, '#140502');
    bgGrad.addColorStop(0.5, '#2e0f06');
    bgGrad.addColorStop(1, '#0a0301');
  } else {
    // cyber por defecto
    bgGrad.addColorStop(0, '#020617');
    bgGrad.addColorStop(0.5, '#090f26');
    bgGrad.addColorStop(1, '#030712');
  }
  ctx.fillStyle = bgGrad;
  ctx.fillRect(0, 0, width, height);

  // 2. Rejilla de perspectiva cibernética (Synthwave 3D Grid)
  const horizonY = Math.round(height * 0.48);
  const vpX = Math.round(width * 0.5);

  let gridColor = 'rgba(56, 189, 248, 0.22)';
  let accentColor = '#38bdf8';
  if (theme === 'jail') {
    gridColor = 'rgba(245, 158, 11, 0.22)';
    accentColor = '#f59e0b';
  } else if (theme === 'divine') {
    gridColor = 'rgba(253, 224, 71, 0.24)';
    accentColor = '#fde047';
  } else if (theme === 'danger') {
    gridColor = 'rgba(244, 63, 94, 0.25)';
    accentColor = '#f43f5e';
  } else if (theme === 'toxic' || theme === 'garbage_collector') {
    gridColor = 'rgba(34, 197, 94, 0.26)';
    accentColor = '#22c55e';
  } else if (theme === 'recursive' || theme === 'stack_overflow') {
    gridColor = 'rgba(168, 85, 247, 0.26)';
    accentColor = '#a855f7';
  } else if (theme === 'microwave' || theme === 'prototype_microwave') {
    gridColor = 'rgba(249, 115, 22, 0.28)';
    accentColor = '#f97316';
  }

  ctx.strokeStyle = gridColor;
  ctx.lineWidth = 1;

  // Líneas de perspectiva horizontales con espaciado exponencial
  for (let dy = 2; dy < height - horizonY; dy = Math.round(dy * 1.38 + 2)) {
    const y = horizonY + dy;
    if (y < height) {
      ctx.beginPath();
      ctx.moveTo(0, y + 0.5);
      ctx.lineTo(width, y + 0.5);
      ctx.stroke();
    }
  }

  // Líneas radiales que nacen del punto de fuga
  for (let x = -width; x <= width * 2; x += 28) {
    ctx.beginPath();
    ctx.moveTo(vpX, horizonY);
    ctx.lineTo(x, height);
    ctx.stroke();
  }

  // 3. Horizonte luminoso
  ctx.strokeStyle = accentColor;
  ctx.beginPath();
  ctx.moveTo(0, horizonY - 0.5);
  ctx.lineTo(width, horizonY - 0.5);
  ctx.stroke();

  // 4. Scanlines horizontales sutiles estilo CRT retro
  ctx.fillStyle = 'rgba(0, 0, 0, 0.18)';
  for (let y = 0; y < height; y += 2) {
    ctx.fillRect(0, y, width, 1);
  }

  // 5. Marco y rótulos de diagnóstico retro
  const boxW = width - 48;
  const boxH = 44;
  const boxX = 24;
  const boxY = Math.round(height * 0.16);

  ctx.fillStyle = 'rgba(5, 8, 20, 0.88)';
  ctx.fillRect(boxX, boxY, boxW, boxH);
  ctx.strokeStyle = accentColor;
  ctx.strokeRect(boxX + 0.5, boxY + 0.5, boxW - 1, boxH - 1);

  // Esquinas reforzadas
  ctx.fillStyle = accentColor;
  ctx.fillRect(boxX, boxY, 3, 3);
  ctx.fillRect(boxX + boxW - 3, boxY, 3, 3);
  ctx.fillRect(boxX, boxY + boxH - 3, 3, 3);
  ctx.fillRect(boxX + boxW - 3, boxY + boxH - 3, 3, 3);

  // Textos
  ctx.font = 'bold 7px monospace';
  ctx.fillStyle = accentColor;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(String(title).toUpperCase(), width / 2, boxY + 14);

  ctx.font = '5.5px monospace';
  ctx.fillStyle = '#94a3b8';
  ctx.fillText(String(subtitle), width / 2, boxY + 28);

  ctx.restore();
}

/**
 * Crea un Data-URI de fallback para 320x180 px.
 * Utiliza un canvas off-screen si está en navegador, o SVG nítido en Node/SSR.
 */
export function createCutsceneFallbackImage(title = 'SYSTEM ARCHIVE', subtitle = 'BUFFERING SCENE...', theme = 'cyber') {
  if (typeof document !== 'undefined' && typeof document.createElement === 'function') {
    try {
      const canvas = document.createElement('canvas');
      canvas.width = 320;
      canvas.height = 180;
      const ctx = canvas.getContext('2d');
      if (ctx) {
        renderFallbackToContext(ctx, 320, 180, title, subtitle, theme);
        return canvas.toDataURL('image/webp');
      }
    } catch {
      // Fallback a SVG si canvas falla
    }
  }

  // Fallback SVG autónomo y universal
  const strokeColor = theme === 'jail' ? '#f59e0b' : (theme === 'divine' ? '#fde047' : (theme === 'danger' ? '#f43f5e' : '#38bdf8'));
  const bgColor = theme === 'jail' ? '#14080d' : (theme === 'divine' ? '#0d041a' : (theme === 'danger' ? '#1a050f' : '#030712'));
  const svg = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 320 180" width="320" height="180" shape-rendering="crispEdges">
    <rect width="320" height="180" fill="${bgColor}"/>
    <line x1="0" y1="90" x2="320" y2="90" stroke="${strokeColor}" stroke-width="1" opacity="0.6"/>
    <line x1="160" y1="90" x2="10" y2="180" stroke="${strokeColor}" stroke-width="1" opacity="0.2"/>
    <line x1="160" y1="90" x2="90" y2="180" stroke="${strokeColor}" stroke-width="1" opacity="0.2"/>
    <line x1="160" y1="90" x2="230" y2="180" stroke="${strokeColor}" stroke-width="1" opacity="0.2"/>
    <line x1="160" y1="90" x2="310" y2="180" stroke="${strokeColor}" stroke-width="1" opacity="0.2"/>
    <rect x="30" y="30" width="260" height="44" fill="#050814" stroke="${strokeColor}" stroke-width="1"/>
    <text x="160" y="50" fill="${strokeColor}" font-family="monospace" font-size="8" font-weight="bold" text-anchor="middle">${title}</text>
    <text x="160" y="64" fill="#94a3b8" font-family="monospace" font-size="6" text-anchor="middle">${subtitle}</text>
  </svg>`;
  return 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(svg.trim());
}

