/**
 * Alias retrocompatible
 */
export const CutsceneImages = CUTSCENE_IMAGES;

/**
 * Obtiene la imagen de una escena o devuelve un fallback nítido
 * si la clave no existe o está en blanco.
 */
export function getCutsceneImage(key, fallbackTitle = 'SYSTEM ARCHIVE', theme = 'cyber') {
  if (key && CUTSCENE_IMAGES[key]) {
    return CUTSCENE_IMAGES[key];
  }
  return createCutsceneFallbackImage(fallbackTitle, 'BUFFERING SCENE...', theme);
}
